mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.TEMPLATE_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.TEMPLATE_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.TEMPLATE_ID = #{templateId}
AND T1.TECH_ROLE_CD = #{techRoleCd}
AND T1.ACTIVE_YN = #{activeYn}

WHERE 1=1

  AND (UPPER(NVL(T1.ITEM_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.ITEM_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.TEMPLATE_ID = #{templateId}
AND T1.ITEM_ID = #{itemId}
AND T1.ACTIVE_YN = #{activeYn}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.TEMPLATE_ID AS TEMPLATE_ID, T1.TEMPLATE_NAME AS TEMPLATE_NAME, T1.TECH_ROLE_CD AS TECH_ROLE_CD,
           T1.ACTIVE_YN AS ACTIVE_YN, T1.REMARK AS REMARK, T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM,
           T1.CHG_USER_ID AS CHG_USER_ID, T1.CHG_DTM AS CHG_DTM
      FROM TB_IF_SURVEY_TMPL_PILOT T1

     ORDER BY T1.TEMPLATE_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.TEMPLATE_ID AS TEMPLATE_ID, T.TEMPLATE_NAME AS TEMPLATE_NAME, T1.ITEM_ID AS ITEM_ID, T1.ITEM_NAME AS ITEM_NAME,
           T1.ITEM_TYPE_CD AS ITEM_TYPE_CD, T1.REQUIRED_YN AS REQUIRED_YN, T1.SORT_NO AS SORT_NO, T1.ACTIVE_YN AS ACTIVE_YN,
           T1.REMARK AS REMARK, T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM, T1.CHG_USER_ID AS CHG_USER_ID, T1.CHG_DTM AS CHG_DTM
      FROM TB_IF_SURVEY_ITEM_PILOT T1
      LEFT JOIN TB_IF_SURVEY_TMPL_PILOT T ON T.TEMPLATE_ID = T1.TEMPLATE_ID

     ORDER BY T1.TEMPLATE_ID ASC, T1.SORT_NO ASC, T1.ITEM_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.update:
UPDATE TB_IF_SURVEY_ITEM_PILOT SET ITEM_NAME=#{itemName}, ITEM_TYPE_CD=#{itemTypeCd}, REQUIRED_YN=#{requiredYn},
  SORT_NO=#{sortNo}, ACTIVE_YN=#{activeYn}, REMARK=#{remark}, CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE TEMPLATE_ID=#{templateId} AND ITEM_ID=#{itemId}
